diff --git a/tests/tui/native-index-workflows.test.js b/tests/tui/native-index-workflows.test.js
index 85ac07de6..83997372b 100644
--- a/tests/tui/native-index-workflows.test.js
+++ b/tests/tui/native-index-workflows.test.js
@@ -315,9 +315,16 @@ try {
           } else {
             await closeCatalog(); terminal.write('R'); await rendered('Ready; Enter runs a canonical search');
             const searchAfter = await last('native-search-');
-            terminal.write('nativeWorkflowAnswer\t\x15code\t\x15memory\t\x155\t\t\t\x15{"ann":false}\r');
+            // Paste each literal field through the real native input dispatcher.
+            // Per-character events redraw the complete terminal for every byte;
+            // batching preserves the same edit/tab/submit sequence and values.
+            await recordFixturePhase('published-search-form:ready');
+            terminal.write(paste('nativeWorkflowAnswer') + '\t\x15' + paste('code') + '\t\x15'
+              + paste('memory') + '\t\x15' + paste('5') + '\t\t\t\x15' + paste('{"ann":false}') + '\r');
+            await recordFixturePhase('published-search-form:submitted');
             const search = await settled('native-search-', 'query', searchAfter);
             assert.ok(search.hits.some(hit => hit.file === 'answer.js'), JSON.stringify(search));
+            await recordFixturePhase('published-search-result:ready');
             await rendered('answer.js'); terminal.write('\x1b'); await rendered('Tab pane'); terminal.write('q');
           }
         } else if (mode === 'stats-conflict') {
@@ -462,7 +469,13 @@ try {
   const owned = [...new Set(recorded.flatMap(row => ['native', 'proxy', 'supervisor', 'job'].map(key => row[key]).filter(Number.isInteger)))];
   assert.deepEqual(owned.filter(isProcessAlive), []);
   if (mode !== 'search-published') assert.ok(recorded.some(row => row.request?.op === 'workflow:run' && row.request.method === 'preview'));
-  else assert.ok(recorded.some(row => row.request?.op === 'search:run' && row.request.method === 'query'));
+  else {
+    const queried = recorded.filter(row => row.request?.op === 'search:run' && row.request.method === 'query');
+    assert.equal(queried.length, 1, 'paste/edit input submits exactly one real query');
+    assert.deepEqual(queried[0].request.params, { repoPath: repo,
+      search: { query: 'nativeWorkflowAnswer', mode: 'code', backend: 'memory', top: 5, ann: false } },
+    'the real supervisor receives every unchanged literal field and predicate');
+  }
   if (['build-search', 'validate-published', 'search-published'].includes(mode)) {
     const selected = recorded.find(row => row.request?.op === 'workflow:run' && row.request.method === 'select');
     assert.equal(selected.request.params.kind, 'repo'); assert.equal(selected.request.params.target, repo);
